import type { Metadata } from "next";
import { SITE } from "./site";

// A page that sets its own openGraph no longer inherits the image generated by
// app/opengraph-image.tsx, so every page names it explicitly.
const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Troița: calendarul ortodox, zi de zi.",
};

/**
 * Metadata for one page: title, description, canonical URL and the Open Graph
 * tags that Facebook, WhatsApp and other apps read when a link is shared.
 *
 * Keep titles under ~60 characters (the " · Troița" suffix is added by the
 * layout template) and descriptions under ~155, or Google cuts them off.
 */
export function pageMeta({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const url = path === "/" ? SITE.url : `${SITE.url}${path}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "ro_RO",
      siteName: SITE.name,
      title: `${title} · ${SITE.name}`,
      description,
      url,
      images: [OG_IMAGE],
    },
    twitter: { card: "summary_large_image", title: `${title} · ${SITE.name}`, description, images: [OG_IMAGE.url] },
  };
}
